On Mon, Aug 31, 2026 at 03:39:35PM +0800, Jinjie Ruan wrote:
>
>
>在 2026/8/28 16:48, Coiby Xu 写道:
>> If kexec_add_buffer somehow fails, keys_header will be freed. Depending
>> on /sys/kernel/config/crash_dm_crypt_key/reuse, it will lead to the
>> following two problems if the kexec_file_load syscall is called again,
>>   1. Double free of keys_header if reuse=false
>>   2. UAF of keys_header if reuse=true
>>
>> To address these problems and also make it easier to reason about the
>> code, keep two invariants,
>>   1. keys_header will always be freed at the end of kexec_file_load
>>      syscall except during kdump image unloading for CPU/memory
>>      hot-plugging support
>>   2. There will always be valid keys_header if reuse=true
>>
>> Fixes: 479e58549b0f ("crash_dump: store dm crypt keys in kdump reserved memory")
>> Fixes: 9ebfa8dcaea7 ("crash_dump: reuse saved dm crypt keys for CPU/memory hot-plugging")
>> Reported-by: Sourabh Jain <sourabhjain@linux.ibm.com>
>> Signed-off-by: Coiby Xu <coiby.xu@gmail.com>
>> ---
>>  include/linux/kexec.h        |  6 ++++
>>  kernel/crash_dump_dm_crypt.c | 66 ++++++++++++++++++++++++++----------
>>  kernel/kexec_file.c          |  2 ++
>>  3 files changed, 56 insertions(+), 18 deletions(-)
>>
>> diff --git a/include/linux/kexec.h b/include/linux/kexec.h
>> index 0af8ae4fdd08..0fa8bac04576 100644
>> --- a/include/linux/kexec.h
>> +++ b/include/linux/kexec.h
>> @@ -552,6 +552,12 @@ void set_kexec_sig_enforced(void);
>>  static inline void set_kexec_sig_enforced(void) {}
>>  #endif
>>
>> +#ifdef CONFIG_CRASH_DM_CRYPT
>> +void kexec_file_post_load_cleanup_dm_crypt(struct kimage *image);
>> +#else
>> +static inline void kexec_file_post_load_cleanup_dm_crypt(struct kimage *image) {}
>> +#endif
>> +
>>  #endif /* !defined(__ASSEBMLY__) */
>>
>>  #endif /* LINUX_KEXEC_H */
>> diff --git a/kernel/crash_dump_dm_crypt.c b/kernel/crash_dump_dm_crypt.c
>> index c685497cd470..4335b6cb1fc4 100644
>> --- a/kernel/crash_dump_dm_crypt.c
>> +++ b/kernel/crash_dump_dm_crypt.c
>> @@ -84,18 +84,25 @@ static int add_key_to_keyring(struct dm_crypt_key *dm_key,
>>  	return r;
>>  }
>>
>> -static void get_keys_from_kdump_reserved_memory(void)
>> +static int get_keys_from_kdump_reserved_memory(void)
>>  {
>>  	struct keys_header *keys_header_loaded;
>> +	size_t keys_header_size;
>>
>> -	arch_kexec_unprotect_crashkres();
>> +	keys_header_size = get_keys_header_size(key_count);
>> +	keys_header = kzalloc(keys_header_size, GFP_KERNEL);
>> +	if (!keys_header)
>> +		return -ENOMEM;
>>
>> +	arch_kexec_unprotect_crashkres();
>>  	keys_header_loaded = kmap_local_page(pfn_to_page(
>>  		kexec_crash_image->dm_crypt_keys_addr >> PAGE_SHIFT));
>>
>> -	memcpy(keys_header, keys_header_loaded, get_keys_header_size(key_count));
>> +	memcpy(keys_header, keys_header_loaded, keys_header_size);
>>  	kunmap_local(keys_header_loaded);
>>  	arch_kexec_protect_crashkres();
>> +
>> +	return 0;
>>  }
>>
>>  static int restore_dm_crypt_keys_to_thread_keyring(void)
>> @@ -286,17 +293,28 @@ static ssize_t config_keys_reuse_show(struct config_item *item, char *page)
>>  static ssize_t config_keys_reuse_store(struct config_item *item,
>>  					   const char *page, size_t count)
>>  {
>> +	bool val;
>> +	int r;
>> +
>>  	if (!kexec_crash_image || !kexec_crash_image->dm_crypt_keys_addr) {
>>  		kexec_dprintk(
>>  			"dm-crypt keys haven't be saved to crash-reserved memory\n");
>>  		return -EINVAL;
>>  	}
>>
>> -	if (kstrtobool(page, &is_dm_key_reused))
>> +	if (kstrtobool(page, &val) || !val)
>>  		return -EINVAL;
>>
>> -	if (is_dm_key_reused)
>> -		get_keys_from_kdump_reserved_memory();
>> +	if (is_dm_key_reused) {
>> +		pr_info("Already got dm-crypt keys, please continue with kexec_file_load syscall\n");
>> +	} else {
>> +		r = get_keys_from_kdump_reserved_memory();
>> +		if (r) {
>> +			pr_warn("Failed to get dm-crypt keys from reserved memory\n");
>> +			return r;
>> +		}
>> +		is_dm_key_reused = true;
>> +	}
>>
>>  	return count;
>>  }
>> @@ -369,9 +387,6 @@ static int build_keys_header(void)
>>  	struct config_key *key;
>>  	int i, r;
>>
>> -	if (keys_header != NULL)
>> -		kvfree(keys_header);
>> -
>>  	keys_header = kzalloc(get_keys_header_size(key_count), GFP_KERNEL);
>>  	if (!keys_header)
>>  		return -ENOMEM;
>> @@ -415,8 +430,7 @@ int crash_load_dm_crypt_keys(struct kimage *image)
>>  		.top_down = false,
>>  		.random = true,
>>  	};
>> -	int r;
>> -
>> +	int r = 0;
>>
>>  	if (key_count <= 0) {
>>  		kexec_dprintk("No dm-crypt keys\n");
>> @@ -424,14 +438,15 @@ int crash_load_dm_crypt_keys(struct kimage *image)
>>  	}
>>
>>  	if (!is_dm_key_reused) {
>> -		image->dm_crypt_keys_addr = 0;
>>  		r = build_keys_header();
>> -		if (r) {
>> -			pr_err("Failed to build dm-crypt keys header, ret=%d\n", r);
>> -			return r;
>> -		}
>> +		if (r)
>> +			goto out;
>>  	}
>>
>> +	/*
>> +	 * keys_header will be copied to reserver memory later and then be
>> +	 * cleaned up at the end of kexec_file_load syscall
>> +	 */
>>  	kbuf.buffer = keys_header;
>>  	kbuf.bufsz = get_keys_header_size(key_count);
>>
>> @@ -441,18 +456,33 @@ int crash_load_dm_crypt_keys(struct kimage *image)
>>  	r = kexec_add_buffer(&kbuf);
>>  	if (r) {
>>  		pr_err("Failed to call kexec_add_buffer, ret=%d\n", r);
>> -		kvfree((void *)kbuf.buffer);
>> -		return r;
>> +		goto out;
>>  	}
>> +
>>  	image->dm_crypt_keys_addr = kbuf.mem;
>>  	image->dm_crypt_keys_sz = kbuf.bufsz;
>>  	kexec_dprintk(
>>  		"Loaded dm crypt keys to kexec_buffer bufsz=0x%lx memsz=0x%lx\n",
>>  		kbuf.bufsz, kbuf.memsz);
>>
>> +out:
>> +	is_dm_key_reused = false;
>
>I think there's still a bug for arm64 here.
>
>When is_dm_key_reused set to true, the outer while loop prematurely
>clears the is_dm_key_reused flag at the end of
>crash_load_dm_crypt_keys() in the very first iteration.
>
>Consequently, subsequent re-entrant calls to crash_load_dm_crypt_keys()
>falsely perceive the keys as not reused, forcing a redundant execution
>of build_keys_header() which overwrites the global keys_header pointer;
>
>This induces a silent kernel memory leak.

Thanks for reviewing this patch and raising the concern! Unless I miss
something, I don't think the global keys_header will be overwritten
because kexec_file_post_load_cleanup_dm_crypt will called to free the
memory during the end of kexec_file_load syscall.

>
>92 >-------/*
> 93 >------- * The location of the kernel segment may make it impossible
>to satisfy
> 94 >------- * the other segment requirements, so we try repeatedly to
>find a
> 95 >------- * location that will work.
> 96 >------- */
> 97 >-------while ((ret = kexec_add_buffer(&kbuf)) == 0) {
> 98 >------->-------/* Try to load additional data */
> 99 >------->-------kernel_segment = &image->segment[kernel_segment_number];
>100 >------->-------ret = load_other_segments(image, kernel_segment->mem,
>101 >------->------->------->------->-------  kernel_segment->memsz, initrd,
>102 >------->------->------->------->-------  initrd_len, cmdline);
>103 >------->-------if (!ret)
>104 >------->------->-------break;
>105
>106 >------->-------/*
>107 >------->------- * We couldn't find space for the other segments;
>erase the
>108 >------->------- * kernel segment and try the next available hole.
>109 >------->------- */
>110 >------->-------image->nr_segments -= 1;
>111 >------->-------kbuf.buf_min = kernel_segment->mem +
>kernel_segment->memsz;
>112 >------->-------kbuf.mem = KEXEC_BUF_MEM_UNKNOWN;
>113 >-------}

Btw, I assume the above text is not related to the discussion, right? 

[...]

-- 
Best regards,
Coiby

Hi all,

Today's linux-next merge of the drm-intel tree got a conflict in:

  drivers/gpu/drm/i915/display/intel_cdclk.c

between commits:

  aad969968824e ("drm/i915/cdclk: Avoid spurious cdclk sanitization on PTL+")
  a154f2ae8eecb ("drm/i915/cdclk: Fix dg2_power_well_count() return type")

from the drm-intel-fixes tree and commits:

  050e8067dcb8f ("drm/i915/cdclk: Hoist intel_cdclk_{pre,post}_notify() calls upwards")
  22d664affc438 ("drm/i915/cdclk: Introduce CDCLK .{pre,post}_notify() vfuncs")
  6dc9d09567047 ("drm/i915/cdclk: Extract bxt_cdclk_pcode_{pre,post}_notify()")
  14890a802ea4d ("drm/i915/cdclk: Extract skl_cdclk_pcode_{pre,post}_notify()")
  1098a94f822d2 ("drm/i915/cdclk: Extract bdw_cdclk_pcode_{pre,post}_notify()")
  e2760d76d1a20 ("drm/i915/cdclk: Unify pcode related debugs")
  9131fd68a86ba ("drm/i915/cdclk: Unify the pcode pre/post notify in bxt_set_cdclk()")
  8961ea13bec45 ("drm/i915/cdclk: s/intel_/dg2_/ for DG2 specific stuff")
  cd4cd31960608 ("drm/i915/cdclk: Drop pointless platform check from bxt_set_cdclk()")
  934b9973f7124 ("drm/i915/cdclk: Stop forcing voltage level to 3 all the time on DG2")
  e68e1b80d1639 ("drm/i915/cdclk: Notify DG2 pcode about pipe power wells regardless of CDCLK")
  3f8c7b2fdd0e8 ("drm/i915/cdclk: Do the DG2 CDCLK/pipe power well notify properly")
  dc2a960b64354 ("drm/i915/cdclk: Pass CDCLK in MHz to pcode on DG2")
  bed6347ae41b0 ("drm/i915/cdclk: Don't bail if pcode post nofify fails")
  dcf423710d025 ("drm/i915/cdclk: Fix dg2_power_well_count() return type")
  1ceb1ef81c32e ("drm/i915/cdclk: Introduce has_cd2x_pipe_select()")
  1786d26887817 ("drm/i915/cdclk: Avoid spurious cdclk sanitization on PTL+")

from the drm-intel tree.

I fixed it up (see below) and can carry the fix as necessary. This
is now fixed as far as linux-next is concerned, but any non trivial
conflicts should be mentioned to your upstream maintainer when your tree
is submitted for merging.  You may also want to consider cooperating
with the maintainer of the conflicting tree to minimise any particularly
complex conflicts.

diff --combined drivers/gpu/drm/i915/display/intel_cdclk.c
index a1a5720996b70,92e6fca861f64..0000000000000
--- a/drivers/gpu/drm/i915/display/intel_cdclk.c
+++ b/drivers/gpu/drm/i915/display/intel_cdclk.c
@@@ -163,6 -163,9 +163,9 @@@ struct intel_cdclk_funcs 
  	void (*set_cdclk)(struct intel_display *display,
  			  const struct intel_cdclk_config *cdclk_config,
  			  enum pipe pipe);
+ 	int (*pre_notify)(struct intel_display *display);
+ 	int (*post_notify)(struct intel_display *display,
+ 			   const struct intel_cdclk_config *cdclk_config);
  	int (*modeset_calc_cdclk)(struct intel_atomic_state *state);
  	u8 (*calc_voltage_level)(int cdclk);
  };
@@@ -173,11 -176,45 +176,45 @@@ void intel_cdclk_get_cdclk(struct intel
  	display->cdclk.funcs->get_cdclk(display, cdclk_config);
  }
  
+ static int intel_cdclk_pre_notify(struct intel_display *display)
+ {
+ 	int ret;
+ 
+ 	if (!display->cdclk.funcs->pre_notify)
+ 		return 0;
+ 
+ 	ret = display->cdclk.funcs->pre_notify(display);
+ 	if (ret)
+ 		drm_err(display->drm,
+ 			"Failed to inform system about start of CDCLK change (%d)\n", ret);
+ 
+ 	return ret;
+ }
+ 
+ static void intel_cdclk_post_notify(struct intel_display *display,
+ 				    const struct intel_cdclk_config *cdclk_config)
+ {
+ 	int ret;
+ 
+ 	if (!display->cdclk.funcs->post_notify)
+ 		return;
+ 
+ 	ret = display->cdclk.funcs->post_notify(display, cdclk_config);
+ 	if (ret)
+ 		drm_err(display->drm,
+ 			"Failed to inform system about end of CDCLK change (%d)\n", ret);
+ }
+ 
  static void intel_cdclk_set_cdclk(struct intel_display *display,
  				  const struct intel_cdclk_config *cdclk_config,
  				  enum pipe pipe)
  {
+ 	if (intel_cdclk_pre_notify(display))
+ 		return;
+ 
  	display->cdclk.funcs->set_cdclk(display, cdclk_config, pipe);
+ 
+ 	intel_cdclk_post_notify(display, cdclk_config);
  }
  
  static int intel_cdclk_modeset_calc_cdclk(struct intel_atomic_state *state)
@@@ -872,6 -909,19 +909,19 @@@ static u32 bdw_cdclk_freq_sel(int cdclk
  	}
  }
  
+ static int bdw_cdclk_pcode_pre_notify(struct intel_display *display)
+ {
+ 	return intel_parent_pcode_write(display, BDW_PCODE_DISPLAY_FREQ_CHANGE_REQ,
+ 					0x0);
+ }
+ 
+ static int bdw_cdclk_pcode_post_notify(struct intel_display *display,
+ 				       const struct intel_cdclk_config *cdclk_config)
+ {
+ 	return intel_parent_pcode_write(display, HSW_PCODE_DE_WRITE_FREQ_REQ,
+ 					cdclk_config->voltage_level);
+ }
+ 
  static void bdw_set_cdclk(struct intel_display *display,
  			  const struct intel_cdclk_config *cdclk_config,
  			  enum pipe pipe)
@@@ -888,13 -938,6 +938,6 @@@
  		     "trying to change cdclk frequency with cdclk not enabled\n"))
  		return;
  
- 	ret = intel_parent_pcode_write(display, BDW_PCODE_DISPLAY_FREQ_CHANGE_REQ, 0x0);
- 	if (ret) {
- 		drm_err(display->drm,
- 			"failed to inform pcode about cdclk change\n");
- 		return;
- 	}
- 
  	intel_de_rmw(display, LCPLL_CTL,
  		     0, LCPLL_CD_SOURCE_FCLK);
  
@@@ -918,9 -961,6 +961,6 @@@
  	if (ret)
  		drm_err(display->drm, "Switching back to LCPLL failed\n");
  
- 	intel_parent_pcode_write(display, HSW_PCODE_DE_WRITE_FREQ_REQ,
- 				 cdclk_config->voltage_level);
- 
  	intel_de_write(display, CDCLK_FREQ,
  		       DIV_ROUND_CLOSEST(cdclk, 1000) - 1);
  
@@@ -1155,6 -1195,21 +1195,21 @@@ static u32 skl_cdclk_freq_sel(struct in
  	}
  }
  
+ static int skl_cdclk_pcode_pre_notify(struct intel_display *display)
+ {
+ 	return intel_parent_pcode_request(display, SKL_PCODE_CDCLK_CONTROL,
+ 					  SKL_CDCLK_PREPARE_FOR_CHANGE,
+ 					  SKL_CDCLK_READY_FOR_CHANGE,
+ 					  SKL_CDCLK_READY_FOR_CHANGE, 3);
+ }
+ 
+ static int skl_cdclk_pcode_post_notify(struct intel_display *display,
+ 				       const struct intel_cdclk_config *cdclk_config)
+ {
+ 	return intel_parent_pcode_write(display, SKL_PCODE_CDCLK_CONTROL,
+ 					cdclk_config->voltage_level);
+ }
+ 
  static void skl_set_cdclk(struct intel_display *display,
  			  const struct intel_cdclk_config *cdclk_config,
  			  enum pipe pipe)
@@@ -1162,7 -1217,6 +1217,6 @@@
  	int cdclk = cdclk_config->cdclk;
  	int vco = cdclk_config->vco;
  	u32 freq_select, cdclk_ctl;
- 	int ret;
  
  	/*
  	 * Based on WA#1183 CDCLK rates 308 and 617MHz CDCLK rates are
@@@ -1175,16 -1229,6 +1229,6 @@@
  	drm_WARN_ON_ONCE(display->drm,
  			 display->platform.skylake && vco == 8640000);
  
- 	ret = intel_parent_pcode_request(display, SKL_PCODE_CDCLK_CONTROL,
- 					 SKL_CDCLK_PREPARE_FOR_CHANGE,
- 					 SKL_CDCLK_READY_FOR_CHANGE,
- 					 SKL_CDCLK_READY_FOR_CHANGE, 3);
- 	if (ret) {
- 		drm_err(display->drm,
- 			"Failed to inform PCU about cdclk change (%d)\n", ret);
- 		return;
- 	}
- 
  	freq_select = skl_cdclk_freq_sel(display, cdclk, vco);
  
  	if (display->cdclk.hw.vco != 0 &&
@@@ -1220,10 -1264,6 +1264,6 @@@
  	intel_de_write(display, CDCLK_CTL, cdclk_ctl);
  	intel_de_posting_read(display, CDCLK_CTL);
  
- 	/* inform PCU of the change */
- 	intel_parent_pcode_write(display, SKL_PCODE_CDCLK_CONTROL,
- 				 cdclk_config->voltage_level);
- 
  	intel_update_cdclk(display);
  }
  
@@@ -1314,7 -1354,7 +1354,7 @@@ static void skl_cdclk_init_hw(struct in
  	cdclk_config.cdclk = skl_calc_cdclk(0, cdclk_config.vco);
  	cdclk_config.voltage_level = skl_calc_voltage_level(cdclk_config.cdclk);
  
- 	skl_set_cdclk(display, &cdclk_config, INVALID_PIPE);
+ 	intel_cdclk_set_cdclk(display, &cdclk_config, INVALID_PIPE);
  }
  
  static void skl_cdclk_uninit_hw(struct intel_display *display)
@@@ -1325,7 -1365,7 +1365,7 @@@
  	cdclk_config.vco = 0;
  	cdclk_config.voltage_level = skl_calc_voltage_level(cdclk_config.cdclk);
  
- 	skl_set_cdclk(display, &cdclk_config, INVALID_PIPE);
+ 	intel_cdclk_set_cdclk(display, &cdclk_config, INVALID_PIPE);
  }
  
  struct intel_cdclk_vals {
@@@ -2177,6 -2217,11 +2217,11 @@@ static bool pll_enable_wa_needed(struc
  		display->cdclk.hw.vco > 0;
  }
  
+ static bool has_cd2x_pipe_select(struct intel_display *display)
+ {
+ 	return IS_DISPLAY_VER(display, 10, 20) || display->platform.broxton;
+ }
+ 
  static u32 bxt_cdclk_ctl(struct intel_display *display,
  			 const struct intel_cdclk_config *cdclk_config,
  			 enum pipe pipe)
@@@ -2190,7 -2235,7 +2235,7 @@@
  
  	val = bxt_cdclk_cd2x_div_sel(display, cdclk, vco, waveform);
  
- 	if (DISPLAY_VER(display) < 30)
+ 	if (has_cd2x_pipe_select(display))
  		val |= bxt_cdclk_cd2x_pipe(display, pipe);
  
  	/*
@@@ -2220,6 -2265,29 +2265,29 @@@
  	return val;
  }
  
+ static int bxt_cdclk_pcode_pre_notify(struct intel_display *display)
+ {
+ 	/*
+ 	 * BSpec requires us to wait up to 150usec, but that leads to
+ 	 * timeouts; the 2ms used here is based on experiment.
+ 	 */
+ 	return intel_parent_pcode_write_timeout(display, HSW_PCODE_DE_WRITE_FREQ_REQ,
+ 						0x80000000, 2);
+ }
+ 
+ static int bxt_cdclk_pcode_post_notify(struct intel_display *display,
+ 				       const struct intel_cdclk_config *cdclk_config)
+ {
+ 	/*
+ 	 * The timeout isn't specified, the 2ms used here is based on
+ 	 * experiment.
