>> +    int idx = hantro_av1_get_frame_index(ctx, ref);
>> +
>> +    if (idx != AV1_INVALID_IDX)
>> +        return av1_dec->frame_refs[idx].order_hint;
>> +
>> +    return 0;
>> +}
