>> +static int hantro_av1_get_msb(u32 n)
>> +{
>> +    if (n == 0)
>> +        return 0;
>> +    return 31 ^ __builtin_clz(n);
>> +}
>> +
>> +static short hantro_av1_resolve_divisor_32(u32 d, short *shift)
>> +{
>> +    int f;
>> +    u64 e;
>> +
>> +    *shift = hantro_av1_get_msb(d);
>> +    /* e is obtained from D after resetting the most significant 1 
>> bit. */
>> +    e = d - ((u32)1 << *shift);
>> +    /* Get the most significant DIV_LUT_BITS (8) bits of e into f */
>> +    if (*shift > DIV_LUT_BITS)
>> +        f = AV1_DIV_ROUND_UP_POW2(e, *shift - DIV_LUT_BITS);
>> +    else
>> +        f = e << (DIV_LUT_BITS - *shift);
>> +    if (f > DIV_LUT_NUM)
>> +        return -1;
>> +    *shift += DIV_LUT_PREC_BITS;
>> +    /* Use f as lookup into the precomputed table of multipliers */
>> +    return div_lut[f];
>> +}
>> +
>> +static void hantro_av1_get_shear_params(const u32 *params, s64 *alpha,
>> +                    s64 *beta, s64 *gamma, s64 *delta)
>> +{
>> +    const int *mat = params;
>> +    short shift;
>> +    short y;
>> +    long long gv, dv;
>> +
>> +    if (mat[2] <= 0)
>> +        return;
>> +
>> +    *alpha = clamp_val(mat[2] - (1 << WARPEDMODEL_PREC_BITS), 
>> S16_MIN, S16_MAX);
>> +    *beta = clamp_val(mat[3], S16_MIN, S16_MAX);
>> +
>> +    y = hantro_av1_resolve_divisor_32(abs(mat[2]), &shift) * (mat[2] 
>> < 0 ? -1 : 1);
>> +
>> +    gv = ((long long)mat[4] * (1 << WARPEDMODEL_PREC_BITS)) * y;
>> +
>> +    *gamma = clamp_val((int)AV1_DIV_ROUND_UP_POW2_SIGNED(gv, shift), 
>> S16_MIN, S16_MAX);
>> +
>> +    dv = ((long long)mat[3] * mat[4]) * y;
>> +    *delta = clamp_val(mat[5] -
>> +        (int)AV1_DIV_ROUND_UP_POW2_SIGNED(dv, shift) - (1 << 
>> WARPEDMODEL_PREC_BITS),
>> +        S16_MIN, S16_MAX);
>> +
>> +    *alpha = AV1_DIV_ROUND_UP_POW2_SIGNED(*alpha, 
>> WARP_PARAM_REDUCE_BITS)
>> +         * (1 << WARP_PARAM_REDUCE_BITS);
>> +    *beta = AV1_DIV_ROUND_UP_POW2_SIGNED(*beta, WARP_PARAM_REDUCE_BITS)
>> +        * (1 << WARP_PARAM_REDUCE_BITS);
