>> +int hantro_av1_tile_log2(int target)
>> +{
>> +    int k;
>> +
>> +    /*
>> +     * returns the smallest value for k such that 1 << k is greater
>> +     * than or equal to target
>> +     */
>> +    for (k = 0; (1 << k) < target; k++)
>> +        ;
>> +
>> +    return k;
>> +}
