>> +void hantro_av1_set_tile_info(struct hantro_ctx *ctx)
>> +{
>> +    struct hantro_av1_dec_hw_ctx *av1_dec = &ctx->av1_dec;
>> +    struct hantro_av1_dec_ctrls *ctrls = &av1_dec->ctrls;
>> +    const struct v4l2_av1_tile_info *tile_info = 
>> &ctrls->frame->tile_info;
>> +    const struct v4l2_ctrl_av1_tile_group_entry *group_entry =
>> +        ctrls->tile_group_entry;
>> +    u8 *dst = av1_dec->tile_info.cpu;
>> +    int tile0, tile1;
>> +
>> +    memset(dst, 0, av1_dec->tile_info.size);
>> +
>> +    for (tile0 = 0; tile0 < tile_info->tile_cols; tile0++) {
>> +        for (tile1 = 0; tile1 < tile_info->tile_rows; tile1++) {
>> +            int tile_id = tile1 * tile_info->tile_cols + tile0;
>> +            u32 start, end;
>> +            u32 y0 =
>> +                tile_info->height_in_sbs_minus_1[tile1] + 1;
>> +            u32 x0 = tile_info->width_in_sbs_minus_1[tile0] + 1;
>> +
>> +            /* tile size in SB units (width,height) */
>> +            *dst++ = x0;
>> +            *dst++ = 0;
>> +            *dst++ = 0;
>> +            *dst++ = 0;
>> +            *dst++ = y0;
>> +            *dst++ = 0;
>> +            *dst++ = 0;
>> +            *dst++ = 0;
>> +
>> +            /* tile start position */
>> +            start = group_entry[tile_id].tile_offset - 
>> group_entry[0].tile_offset;
>> +            *dst++ = start & 255;
>> +            *dst++ = (start >> 8) & 255;
>> +            *dst++ = (start >> 16) & 255;
>> +            *dst++ = (start >> 24) & 255;
>> +
>> +            /* number of bytes in tile data */
>> +            end = start + group_entry[tile_id].tile_size;
>> +            *dst++ = end & 255;
>> +            *dst++ = (end >> 8) & 255;
>> +            *dst++ = (end >> 16) & 255;
>> +            *dst++ = (end >> 24) & 255;
>> +        }
>> +    }
>> +}
